update_rule.pseudocode:
if day == 0:
  if network_type == 'small_world':
    graph.social = watts_strogatz_graph(N=population_size, k=average_degree, p=small_world_rewiring_p)
  else if network_type == 'erdos_renyi':
    graph.social = erdos_renyi_graph(N=population_size, p=average_degree/(population_size-1))
  else if network_type == 'scale_free':
    graph.social = barabasi_albert_graph(N=population_size, m=max(1,int(average_degree/2)))
  state.person_neighbors = adjacency lists from graph.social
else:
  pass

for each person:
  draw today's location sequence consistent with location_mix_* fractions
  for each visit in sequence:
    select a location of that type with available capacity
    append (person_id, location_id, time_slot) to state.attendance
aggregate compliance_by_location_type by checking mask_adoption_state at time of entry

violations = 0; checks = 0
for each (person, location, time_slot) in state.attendance:
  required = state.policy.mandate_active and (location.type in mandate_target_location_types) and (location.mask_requirement or state.policy.mandate_strictness > 0)
  if required:
    checks += 1
    effective_enforcement = base_enforcement_level * state.policy.enforcement_probability
    if person.mask_adoption_state == 0:
      if rand() < effective_enforcement:
        violations += 1
        person.perceived_cost += state.policy.fine_amount * mandate_penalty_salience
        record state.enforcement_actions.append({person, location, fine_amount})
observable.violation_rate_daily = violations / max(checks,1)

if day % restock_period_days == 0:
  for retailer in retailers:
    retailer.mask_inventory += retailer_restock_rate * mask_supply_level * population_size / retailers_count
for retailer in retailers:
  demand_est = recent purchases (rolling window)
  supply = retailer.mask_inventory
  price_factor = 1 + price_elasticity * (demand_est - supply) / max(supply + 1,1)
  retailer.mask_price = max(0.1, base_mask_price * price_factor)
  set quality-specific prices by multipliers
purchases = 0
for person in persons:
  if needs_replacement(replacement_interval_mean_days, std=replacement_interval_std_days) or (person.intends_to_adopt and person.mask_quality_owned == 'none'):
    choose quality q by quality distribution weighted by budget affordability
    price_q = retailer.price[q]
    affordable = person.budget >= min_affordable_fraction * price_q
    if affordable:
      find retailer with inventory[q] > 0
      if found:
        buy 1 unit; purchases += 1; decrement inventory; person.mask_quality_owned = q; person.perceived_cost = price_q * budget_constraint_slope
observable.price_daily = mean(current retailer prices across qualities weighted by sales)
observable.purchases_daily = purchases
